 if (!supportCheck(claim, claim.citations)) return abstain(claim);
}
return releaseWithPhaseTimings(draft);
// Support checking is a specified gate; the bounded reference test checks only citation membership.

// Online verification (n6): current = {tenantId, aclEpoch, revision, allowedIds} comes from the source ACL authority, not from the pack.
